    unsigned int sampleRate;
    unsigned int bufferSize;
    unsigned int nBuffers;
    unsigned int nUserChannels[2];
    unsigned int nDeviceChannels[2];
    unsigned int channelOffset[2];
    unsigned long latency[2];
    RtAudioFormat userFormat;
    RtAudioFormat deviceFormat[2];
    StreamMutex mutex;
    CallbackInfo callbackInfo;
    ConvertInfo convertInfo[2];
    double streamTime;
#if defined(HAVE_GETTIMEOFDAY)
    struct timeval lastTickTimestamp;
#endif
    RtApiStream()
    :apiHandle(0), deviceBuffer(0) {}
  };
  typedef S24 Int24;
  typedef signed short Int16;
  typedef signed int Int32;
  typedef float Float32;
  typedef double Float64;
  std::ostringstream errorStream_;
  std::string errorText_;
  RtAudioErrorCallback errorCallback_;
  bool showWarnings_;
  std::vector<RtAudio::DeviceInfo> deviceList_;
  unsigned int currentDeviceId_;
  RtApiStream stream_;
  virtual void probeDevices( void );
  virtual bool probeDeviceOpen( unsigned int deviceId, StreamMode mode, unsigned int channels,
